fn solve(queries: Vec<(i8, i8)>) -> Vec<i8> {
    // Helper function to compute S(k)
    // S(k) = k/2 if k even
    // S(k) = -(k+1)/2 if k odd
    fn prefix_sum(k: i8) -> i8 {
        if k == 0 {
            0
        } else if k % 2 == 0 {
            k / 2
        } else {
            -((k as i16 + 1) / 2) as i8 // cast to i16 to avoid overflow in addition and division
        }
    }

    queries
        .into_iter()
        .map(|(l, r)| {
            // sum from l to r = S(r) - S(l - 1)
            let sum_r = prefix_sum(r);
            let sum_l_1 = prefix_sum(l - 1);
            sum_r - sum_l_1
        })
        .collect()
}